{
  "name": "TopMode 主动稳频二极管激光器",
  "name_en": "TopMode Actively Stabilized Diode Laser",
  "manufacturer": "TOPTICA",
  "description": "TOPTICA 的 TopMode 是一款带主动稳定功能的二极管激光器。该设备可通过串口控制激光使能、查询控制器与各控制板状态，并读取激光波长、强度、模式跳变及校正相关信息，适用于需要稳定窄线宽激光输出的实验场景。",
  "description_en": "The TOPTICA TopMode is an actively stabilized diode laser. It can be controlled over a serial interface to enable laser emission, query controller and board health, and read wavelength, intensity, mode-hop, and correction-related information for experiments requiring stable narrow-linewidth laser output.",
  "tag_hints": [
    "diode laser",
    "active laser stabilization",
    "narrow-linewidth laser",
    "serial instrument control",
    "laser wavelength monitoring",
    "mode-hop monitoring",
    "TEC and current control"
  ],
  "actions": [
    {
      "action_name": "auto-display",
      "description": "发送参数显示请求",
      "description_en": "send a display request for a parameter"
    },
    {
      "action_name": "auto-enable",
      "description": "获取/设置激光出光使能状态",
      "description_en": "get/set laser emission enable state"
    },
    {
      "action_name": "auto-execute",
      "description": "执行 TopMode 控制语言命令",
      "description_en": "execute a TopMode control-language command"
    },
    {
