      "description": "重启系统控制器",
      "description_en": "reboot the system controller"
    },
    {
      "action_name": "auto-reference",
      "description": "查询参数参考值",
      "description_en": "query a parameter reference value"
    },
    {
      "action_name": "auto-set",
      "description": "设置参数值",
      "description_en": "set a parameter value"
    },
    {
      "action_name": "auto-laser",
      "description": "获取指定激光通道对象",
      "description_en": "get a specific laser channel object"
    },
    {
      "action_name": "auto-locked",
      "description": "获取钥匙开关锁定状态",
      "description_en": "get key-switch lock status"
    },
    {
      "action_name": "auto-interlock",
      "description": "获取联锁开关开路状态",
      "description_en": "get interlock open state"
    },
    {
      "action_name": "auto-firmware",
      "description": "获取控制器固件版本",
      "description_en": "get controller firmware version"
    },
    {
      "action_name": "auto-fpga_status",
      "description": "获取 FPGA 健康状态",
      "description_en": "get FPGA health status"
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取控制器序列号",
      "description_en": "get controller serial number"
    },
    {
      "action_name": "auto-temperature_status",
      "description": "获取温度控制板健康状态",
      "description_en": "get temperature controller board health status"
    },
    {
      "action_name": "auto-current_status",
      "description": "获取电流控制板健康状态",
      "description_en": "get current controller board health status"
    },
    {
      "action_name": "auto-model",
      "description": "获取设备型号",
      "description_en": "get device model"
    },
    {
      "action_name": "auto-wavelength",
      "description": "获取激光波长",
      "description_en": "get laser wavelength"
    },
    {
      "action_name": "auto-production_date",
      "description": "获取生产日期",
      "description_en": "get production date"
    },
    {
      "action_name": "auto-is_connected",
      "description": "获取连接状态",
      "description_en": "get connection status"
    },
    {
      "action_name": "auto-on_time",
      "description": "获取累计上电时间",
      "description_en": "get accumulated power-on time"
    },
    {
      "action_name": "auto-charm_status",
      "description": "获取 Charm 控制器状态",
      "description_en": "get Charm controller status"
    },
    {
      "action_name": "auto-temperature_control_status",
      "description": "获取温度控制状态",
      "description_en": "get temperature control status"
    },
    {
      "action_name": "auto-current_control_status",
      "description": "获取电流控制状态",
      "description_en": "get current control status"
    },
    {
      "action_name": "auto-tec_status",
      "description": "获取 TEC 状态",
      "description_en": "get TEC status"
    },
    {
      "action_name": "auto-intensity",
      "description": "获取激光强度",
      "description_en": "get laser intensity"
    },
    {
      "action_name": "auto-mode_hop",
      "description": "获取模式跳变状态",
      "description_en": "get mode-hop status"
    },
    {
      "action_name": "auto-lock_start",
      "description": "获取锁定开始信息",
      "description_en": "get lock start information"
    },
    {
      "action_name": "auto-first_mode_hop_time",
      "description": "获取首次模式跳变时间",
      "description_en": "get first mode-hop time"
    },
    {
      "action_name": "auto-latest_mode_hop_time",
      "description": "获取最近一次模式跳变时间",
      "description_en": "get latest mode-hop time"
    },
    {
      "action_name": "auto-correction_status",
      "description": "获取校正状态",
      "description_en": "get correction status"
    },
    {
      "action_name": "auto-correction",
      "description": "获取校正值",
      "description_en": "get correction value"
    }
  ]
}

